def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = sum(1 for a in op if a == 'C')
    op_d = n - op_c
    last_op = op[-1]
    last_my = my[-1]

    def run_len(seq):
        k = 0
        for a in reversed(seq):
            if a == 'D':
                k += 1
            else:
                break
        return k

    # Endgame: exploit cooperative opponents, avoid being exploited by defectors
    if n >= 97:
        if op_c >= int(0.75 * n):
            return 'D'
        if op_c >= int(0.5 * n):
            return 'D' if rng.random() < 0.7 else 'C'
        return 'C'

    if n < 6:
        if last_op == 'D':
            return 'D' if rng.random() < 0.85 else 'C'
        return 'C'

    # Pure defector detection: defend, rarely probe
    if op_d >= n - 1 and n >= 8:
        return 'C' if rng.random() < 0.05 else 'D'

    # Highly cooperative opponent: sustain CC, with very rare small probes
    if op_c >= int(0.9 * n) and n >= 12:
        return 'D' if rng.random() < 0.04 else 'C'

    # Recent behavior
    w = min(10, n)
    recent_op = op[-w:]
    recent_c = sum(1 for a in recent_op if a == 'C')
    recent_rate = recent_c / float(w)

    # Recent mostly cooperative: cooperate, gentle probing
    if recent_rate >= 0.8:
        if last_op == 'D':
            return 'D' if rng.random() < 0.75 else 'C'
        return 'D' if rng.random() < 0.05 else 'C'

    # Recent mostly defecting: defend, occasionally attempt reset
    if recent_rate <= 0.2:
        streak = run_len(op)
        if streak >= 4 and rng.random() < 0.2:
            return 'C'
        return 'D'

    # Mixed: tit-for-tat with limited forgiveness
    if last_op == 'D':
        if last_my == 'D':
            # mutual defection — try restart occasionally
            return 'C' if rng.random() < 0.18 else 'D'
        # we were exploited — retaliate firmly
        return 'D' if rng.random() < 0.9 else 'C'

    # last_op == 'C': reciprocate, but probe occasionally if we've been too nice
    my_c = sum(1 for a in my if a == 'C')
    if n >= 15 and my_c >= 0.85 * n and rng.random() < 0.06:
        return 'D'
    return 'C'
